export type BooleanFilter = (typeof booleanFilters)[number];
export type SearchAd = Partial<AdvertisementsModel> &
  Pick<
    AdvertisementsModel,
    | 'id'
    | 'street'
    | 'number'
    | 'tradeType'
    | 'assetType'
    | 'price'
    | 'rooms'
    | 'floor'
    | 'totalSquareMeters'
    | 'city'
    | 'neighborhood'
  > & { exclusivity?: boolean };

export interface SearchFixtureData {
  ads: SearchAd[];
}

export function makeAd(
  id: number,
  overrides: Partial<SearchAd> = {},
): SearchAd {
  return {
    ...Object.fromEntries(booleanFilters.map(([, key]) => [key, false])),
    id,
    street: `QA Search ${id}`,
    number: 1,
    tradeType: 'מכירה',
    assetType: 'דירה',
    price: 1000000,
    rooms: '3',
    floor: 2,
    totalFloors: 18,
    totalSquareMeters: 80,
    city: 'חיפה',
    neighborhood: 'הדר',
    mainPicture: '',
    pictures: [],
    creationDate: '2026-01-01T00:00:00Z',
    entryDate: '2026-12-01T00:00:00Z',
    description: 'Synthetic search test listing',
    airConditioning: false,
    ...overrides,
  };
}

